SELECT s.id, s.name, s.description
FROM c2k_system s
WHERE s.tenant_id = #{tenantId}
  AND (#{admin} OR EXISTS (
      SELECT 1 FROM c2k_system_grant g
      WHERE g.tenant_id = s.tenant_id AND g.system_id = s.id
        AND g.member_id = #{userId} AND g.action = 'catalog.read'
  ) OR EXISTS (

  ))
ORDER BY s.name, s.id

SELECT s.id, s.name, s.description
FROM c2k_system s
WHERE s.tenant_id = #{tenantId} AND s.id = #{id}
  AND (#{admin} OR EXISTS (
      SELECT 1 FROM c2k_system_grant g
      WHERE g.tenant_id = s.tenant_id AND g.system_id = s.id
        AND g.member_id = #{userId} AND g.action = 'catalog.read'
  ) OR EXISTS (

  ))

mapper.delete:
DELETE FROM c2k_system_grant
WHERE tenant_id = #{tenantId} AND system_id = #{systemId}
  AND member_id = #{memberId} AND action = 'catalog.read'
